#include <iostream>
using namespace std;

class FishBag {
    int count;
public:
    FishBag(int c) : count(c) {}

    bool operator==(const FishBag& other) const {
        return count == other.count;
    }
};

int main() {
    int x = 0;
    int y = 0;
    cin >> x >> y;

    FishBag a(x);
    FishBag b(y);
    cout << "两袋小鱼干一样多吗？" << ((a == b) ? "一样喵" : "不一样喵") << endl;
    cout << "同一袋跟自己比呢？" << ((a == a) ? "一样喵" : "不一样喵") << endl;
    return 0;
}

